#!/usr/bin/env bash
set -euo pipefail

# ── build-rn-ios.sh ─────────────────────────────────────────────────
# Builds a React Native / Expo project for iOS simulator, launches it,
# and takes a screenshot. Used as a fallback when the project doesn't
# support React Native Web.
#
# Auto-detects whether the project uses Expo or bare React Native CLI,
# boots a simulator if needed, builds & installs the app, then captures
# a launch screenshot.
#
# Exit codes:
#   0 = build succeeded (screenshot captured)
#   1 = build failed (compile errors)
#   2 = timed out
#   3 = setup error (no xcrun, no simulator, missing deps, etc.)
#
# Usage:
#   ./build-rn-ios.sh --project-dir /path/to/project [--simulator 'iPhone 17 Pro'] [--timeout 300] [--screenshot /path/to/output.png]
#
# Output (structured for agent parsing):
#   BUILD_STATUS:SUCCESS | FAILED | TIMEOUT | ERROR
#   BUILD_TYPE:expo | react-native-cli
#   SIMULATOR_NAME:<name>
#   SIMULATOR_UDID:<udid>
#   SCREENSHOT_PATH:<path>
#   ERRORS_FILE:<path>
#   ERROR_COUNT:<number>
# ────────────────────────────────────────────────────────────────────

PROJECT_DIR=""
SIMULATOR=""
TIMEOUT=300
SCREENSHOT_PATH=""
LOG_FILE=""

# ── Parse args ─────────────────────────────────────────────────────
while [[ $# -gt 0 ]]; do
  case "$1" in
    --project-dir)  PROJECT_DIR="$2"; shift 2 ;;
    --simulator)    SIMULATOR="$2"; shift 2 ;;
    --timeout)      TIMEOUT="$2"; shift 2 ;;
    --screenshot)   SCREENSHOT_PATH="$2"; shift 2 ;;
    *) echo "BUILD_STATUS:ERROR"; echo "Unknown arg: $1"; exit 3 ;;
  esac
done

if [[ -z "$PROJECT_DIR" ]]; then
  echo "BUILD_STATUS:ERROR"
  echo "Missing --project-dir"
  exit 3
fi

cd "$PROJECT_DIR"

# ── Setup log file ─────────────────────────────────────────────────
LOG_DIR="$PROJECT_DIR/.locofy/agent/build-logs"
mkdir -p "$LOG_DIR"
TIMESTAMP=$(date +%Y%m%d_%H%M%S)
LOG_FILE="$LOG_DIR/rn-ios-build_${TIMESTAMP}.log"
ERROR_FILE="$LOG_DIR/rn-ios-errors_${TIMESTAMP}.txt"

# Default screenshot path
if [[ -z "$SCREENSHOT_PATH" ]]; then
  SCREENSHOT_PATH="$LOG_DIR/launch-screenshot_${TIMESTAMP}.png"
fi

# ── Helper: echo to both stdout and log file ─────────────────────
out() {
  echo "$@" | tee -a "$LOG_FILE"
}

# ── Check prerequisites ────────────────────────────────────────────
if ! command -v xcrun &>/dev/null; then
  out "BUILD_STATUS:ERROR"
  out "xcrun not found. Xcode Command Line Tools are required."
  exit 3
fi

if [[ ! -f "package.json" ]]; then
  out "BUILD_STATUS:ERROR"
  out "No package.json found in $PROJECT_DIR"
  exit 3
fi

# ── Detect build type: Expo vs bare React Native CLI ──────────────
BUILD_TYPE=""

if node -e "const p=require('./package.json'); const deps={...p.dependencies,...p.devDependencies}; process.exit(deps['expo'] ? 0 : 1)" 2>/dev/null; then
  BUILD_TYPE="expo"
elif node -e "const p=require('./package.json'); const deps={...p.dependencies,...p.devDependencies}; process.exit(deps['react-native'] ? 0 : 1)" 2>/dev/null; then
  BUILD_TYPE="react-native-cli"
else
  out "BUILD_STATUS:ERROR"
  out "No 'expo' or 'react-native' found in package.json dependencies."
  exit 3
fi

out "BUILD_TYPE:$BUILD_TYPE"

# ── Auto-detect simulator if not provided ──────────────────────────
if [[ -z "$SIMULATOR" ]]; then
  SIMULATOR=$(xcrun simctl list devices available -j 2>/dev/null \
    | python3 -c "
import json, sys
data = json.load(sys.stdin)
for runtime, devices in sorted(data['devices'].items(), reverse=True):
    for d in devices:
        if d['isAvailable'] and 'iPhone' in d['name']:
            print(d['name']); sys.exit(0)
sys.exit(1)
" 2>/dev/null) || true
  if [[ -z "$SIMULATOR" ]]; then
    out "BUILD_STATUS:ERROR"
    out "No available iPhone simulator found. Install one via Xcode."
    exit 3
  fi
fi

out "SIMULATOR_NAME:$SIMULATOR"

# ── Get simulator UDID ────────────────────────────────────────────
SIMULATOR_UDID=$(xcrun simctl list devices available -j 2>/dev/null \
  | python3 -c "
import json, sys
name = '$SIMULATOR'
data = json.load(sys.stdin)
for runtime, devices in sorted(data['devices'].items(), reverse=True):
    for d in devices:
        if d['isAvailable'] and d['name'] == name:
            print(d['udid']); sys.exit(0)
sys.exit(1)
" 2>/dev/null) || true

if [[ -z "$SIMULATOR_UDID" ]]; then
  out "BUILD_STATUS:ERROR"
  out "Could not find UDID for simulator '$SIMULATOR'"
  exit 3
fi

out "SIMULATOR_UDID:$SIMULATOR_UDID"

# ── Boot simulator if not already booted ──────────────────────────
BOOT_STATE=$(xcrun simctl list devices -j 2>/dev/null \
  | python3 -c "
import json, sys
data = json.load(sys.stdin)
for runtime, devices in data['devices'].items():
    for d in devices:
        if d['udid'] == '$SIMULATOR_UDID':
            print(d['state']); sys.exit(0)
" 2>/dev/null) || true

if [[ "$BOOT_STATE" != "Booted" ]]; then
  out "Booting simulator '$SIMULATOR'..."
  xcrun simctl boot "$SIMULATOR_UDID" 2>/dev/null || true
  # Wait for boot
  for i in $(seq 1 15); do
    STATE=$(xcrun simctl list devices -j 2>/dev/null \
      | python3 -c "
import json, sys
data = json.load(sys.stdin)
for runtime, devices in data['devices'].items():
    for d in devices:
        if d['udid'] == '$SIMULATOR_UDID':
            print(d['state']); sys.exit(0)
" 2>/dev/null) || true
    if [[ "$STATE" == "Booted" ]]; then
      break
    fi
    sleep 2
  done
  out "Simulator booted."
else
  out "Simulator already booted."
fi

# Open Simulator.app so the window is visible for screenshots
open -a Simulator 2>/dev/null || true
# Give Simulator.app time to fully launch (needed for osascript calls)
sleep 3

# ── Print config ──────────────────────────────────────────────────
out "BUILD_CONFIG:project=$PROJECT_DIR"
out "BUILD_CONFIG:build_type=$BUILD_TYPE"
out "BUILD_CONFIG:simulator=$SIMULATOR ($SIMULATOR_UDID)"
out "BUILD_CONFIG:timeout=${TIMEOUT}s"
out "BUILD_CONFIG:log=$LOG_FILE"
out "---"

# ── Timeout helper ────────────────────────────────────────────────
timeout_cmd() {
  local secs=$1; shift
  if command -v gtimeout &>/dev/null; then
    gtimeout "$secs" "$@"
  else
    perl -e '
      alarm shift @ARGV;
      $SIG{ALRM} = sub { kill "TERM", $pid; exit 142 };
      $pid = fork();
      if ($pid == 0) { exec @ARGV; die "exec: $!" }
      waitpid($pid, 0);
      exit ($? >> 8);
    ' "$secs" "$@"
  fi
}

# ── Kill any process using the Metro bundler port (8081) ──────────
# Expo run:ios starts its own bundler; if another process holds port 8081
# Expo will prompt interactively, which hangs in non-interactive mode.
METRO_PORT=8081
METRO_PID=$(lsof -ti tcp:$METRO_PORT 2>/dev/null || true)
if [[ -n "$METRO_PID" ]]; then
  out "Port $METRO_PORT is in use (PID $METRO_PID). Killing to avoid interactive prompt..."
  kill "$METRO_PID" 2>/dev/null || true
  sleep 2
fi

# ── Install dependencies if needed ─────────────────────────────────
if [[ ! -d "node_modules" ]]; then
  out "Installing node_modules..."
  npm install >> "$LOG_FILE" 2>&1 || true
fi

# For Expo projects, ensure ios directory exists (prebuild generates it)
if [[ "$BUILD_TYPE" == "expo" && ! -d "ios" ]]; then
  out "Running 'npx expo prebuild --platform ios'..."
  timeout_cmd 120 npx expo prebuild --platform ios >> "$LOG_FILE" 2>&1 || true
fi

# Install CocoaPods if Podfile exists and either:
#   - Pods dir is missing (fresh checkout), OR
#   - Podfile.lock differs from Pods/Manifest.lock (deps changed after merge)
# Try multiple methods: bundled pod, system pod, or npx pod-install.
NEEDS_POD_INSTALL=false
if [[ -f "ios/Podfile" ]]; then
  if [[ ! -d "ios/Pods" ]]; then
    NEEDS_POD_INSTALL=true
    out "Pods directory missing — need to install CocoaPods."
  elif [[ -f "ios/Podfile.lock" && -f "ios/Pods/Manifest.lock" ]]; then
    if ! diff -q "ios/Podfile.lock" "ios/Pods/Manifest.lock" &>/dev/null; then
      NEEDS_POD_INSTALL=true
      out "Podfile.lock differs from Pods/Manifest.lock — dependencies changed, re-installing CocoaPods."
    fi
  elif [[ -f "ios/Podfile.lock" && ! -f "ios/Pods/Manifest.lock" ]]; then
    NEEDS_POD_INSTALL=true
    out "Pods/Manifest.lock missing — need to install CocoaPods."
  fi
fi

if $NEEDS_POD_INSTALL; then
  out "Installing CocoaPods..."
  POD_INSTALLED=false
  # Method 1: bundle exec pod install (if Gemfile exists)
  if [[ -f "Gemfile" ]] && command -v bundle &>/dev/null; then
    (cd ios && bundle exec pod install) >> "$LOG_FILE" 2>&1 && POD_INSTALLED=true || true
  fi
  # Method 2: system pod
  if ! $POD_INSTALLED && command -v pod &>/dev/null; then
    (cd ios && pod install) >> "$LOG_FILE" 2>&1 && POD_INSTALLED=true || true
  fi
  # Method 3: npx pod-install (works without CocoaPods gem)
  if ! $POD_INSTALLED; then
    npx pod-install ios >> "$LOG_FILE" 2>&1 && POD_INSTALLED=true || true
  fi
  # Method 4: Let expo run:ios handle it (it installs pods automatically)
  if ! $POD_INSTALLED; then
    out "Warning: Could not install CocoaPods. Expo will attempt to install pods during build."
  fi
fi

# ── Link native assets for bare RN CLI projects ─────────────────────
# Bare React Native CLI projects use react-native-asset or react-native-link
# to copy fonts/images into native directories (ios/ and android/).
# This is needed when the merge agent adds new fonts or assets.
if [[ "$BUILD_TYPE" == "react-native-cli" ]]; then
  # Check if react-native.config.js declares asset directories
  if [[ -f "react-native.config.js" ]] || [[ -f "react-native.config.ts" ]]; then
    if command -v npx &>/dev/null; then
      out "Linking native assets (react-native-asset)..."
      npx react-native-asset >> "$LOG_FILE" 2>&1 || true
    fi
  fi
fi

# ── Run pre-build scripts from package.json ──────────────────────────
# Some RN CLI projects define preios/prestart scripts that validate assets,
# run react-native-asset, or perform other setup before building.
if [[ "$BUILD_TYPE" == "react-native-cli" ]]; then
  PREIOS_SCRIPT=$(node -e "const p=require('./package.json'); if(p.scripts && p.scripts.preios) console.log(p.scripts.preios)" 2>/dev/null || true)
  if [[ -n "$PREIOS_SCRIPT" ]]; then
    out "Running preios script: $PREIOS_SCRIPT"
    # Run in a subshell to avoid affecting our env; ignore failures (non-critical)
    (eval "$PREIOS_SCRIPT") >> "$LOG_FILE" 2>&1 || {
      out "Warning: preios script failed (non-critical). Continuing with build."
    }
  fi
fi

# ── Start Metro bundler in background ──────────────────────────────
# The app needs Metro to serve the JS bundle. Start it before building
# so the app can connect on launch. We'll kill it after taking the screenshot.
METRO_LOG="$LOG_DIR/metro_${TIMESTAMP}.log"
METRO_PID=""

out "Starting Metro bundler in background..."
if [[ "$BUILD_TYPE" == "expo" ]]; then
  nohup npx expo start --port 8081 > "$METRO_LOG" 2>&1 &
  METRO_PID=$!
else
  nohup npx react-native start --port 8081 > "$METRO_LOG" 2>&1 &
  METRO_PID=$!
fi
disown "$METRO_PID" 2>/dev/null || true
out "METRO_PID:$METRO_PID"

# Wait for Metro to be ready (check for port or log output)
METRO_READY=false
for i in $(seq 1 15); do
  sleep 2
  if curl -sf "http://localhost:8081" > /dev/null 2>&1; then
    METRO_READY=true
    break
  fi
  # Also check if Metro exited prematurely
  if ! kill -0 "$METRO_PID" 2>/dev/null; then
    out "Warning: Metro exited prematurely. Last 10 lines:"
    tail -10 "$METRO_LOG" 2>/dev/null || true
    break
  fi
done

if $METRO_READY; then
  out "Metro bundler ready on port 8081."
else
  out "Warning: Metro may not be ready yet. Proceeding with build anyway."
fi

# ── Build the app ─────────────────────────────────────────────────
BUILD_EXIT=0

if [[ "$BUILD_TYPE" == "expo" ]]; then
  out "Building with Expo (iOS simulator)..."
  # npx expo run:ios handles pod install, xcodebuild, and app launch internally.
  # --no-bundler: Metro is already running in background.
  # --device: target specific simulator by UDID.
  timeout_cmd "$TIMEOUT" \
    npx expo run:ios \
      --device "$SIMULATOR_UDID" \
      --no-bundler \
    >> "$LOG_FILE" 2>&1 || BUILD_EXIT=$?
else
  out "Building with React Native CLI (iOS simulator)..."
  timeout_cmd "$TIMEOUT" \
    npx react-native run-ios \
      --simulator "$SIMULATOR" \
      --no-packager \
    >> "$LOG_FILE" 2>&1 || BUILD_EXIT=$?
fi

# ── Interpret build result ─────────────────────────────────────────
out "---"

# timeout returns 124 (gtimeout) or 142 (perl alarm)
# Helper to kill Metro on exit
cleanup_metro() {
  if [[ -n "$METRO_PID" ]] && kill -0 "$METRO_PID" 2>/dev/null; then
    out "Stopping Metro bundler (PID $METRO_PID)..."
    kill "$METRO_PID" 2>/dev/null || true
  fi
}

if [[ $BUILD_EXIT -eq 124 || $BUILD_EXIT -eq 142 ]]; then
  cleanup_metro
  out "BUILD_STATUS:TIMEOUT"
  out "Build timed out after ${TIMEOUT}s. Log: $LOG_FILE"
  exit 2
elif [[ $BUILD_EXIT -ne 0 ]]; then
  # Check if the build actually succeeded but a post-build step failed
  # (e.g., osascript/Simulator.app activation errors are non-fatal)
  if grep -q '› Build Succeeded' "$LOG_FILE" 2>/dev/null || grep -q 'BUILD SUCCEEDED' "$LOG_FILE" 2>/dev/null; then
    out "Build compilation succeeded (post-build step returned non-zero, likely a Simulator activation issue — treating as success)."
    # Fall through to the success path below
    BUILD_EXIT=0
  else
    out "BUILD_STATUS:FAILED"
    out ""
    # Extract error lines — xcodebuild compile errors
    grep -E ':\d+:\d+: (error|fatal error):' "$LOG_FILE" 2>/dev/null > "$ERROR_FILE" || true
    if [[ ! -s "$ERROR_FILE" ]]; then
      # Fallback: Expo / xcodebuild summary errors
      grep -E '(❌\s+error:|CommandError:|BUILD FAILED)' "$LOG_FILE" 2>/dev/null > "$ERROR_FILE" || true
    fi
    if [[ ! -s "$ERROR_FILE" ]]; then
      # Fallback: RN CLI / Metro bundler errors
      grep -E '(error:|Error:|SyntaxError|TypeError|Cannot find module)' "$LOG_FILE" 2>/dev/null > "$ERROR_FILE" || true
    fi
    if [[ ! -s "$ERROR_FILE" ]]; then
      # Fallback: linker errors
      grep -E '(linker error|undefined symbol|Undefined symbols)' "$LOG_FILE" 2>/dev/null > "$ERROR_FILE" || true
    fi
    if [[ ! -s "$ERROR_FILE" ]]; then
      # Fallback: Podfile / CocoaPods errors
      grep -E '(The sandbox is not in sync|pod install|CocoaPods)' "$LOG_FILE" 2>/dev/null > "$ERROR_FILE" || true
    fi
    if [[ -s "$ERROR_FILE" ]]; then
      ERROR_COUNT=$(wc -l < "$ERROR_FILE" | tr -d ' ')
      out "ERRORS_FILE:$ERROR_FILE"
      out "ERROR_COUNT:$ERROR_COUNT"
      head -20 "$ERROR_FILE" | tee -a "$LOG_FILE"
      if [[ "$ERROR_COUNT" -gt 20 ]]; then
        out "... and $((ERROR_COUNT - 20)) more errors in $ERROR_FILE"
      fi
    else
      rm -f "$ERROR_FILE"
      out "Build failed (no structured errors found). See log: $LOG_FILE"
      out "Last 20 lines of log:"
      tail -20 "$LOG_FILE"
    fi
    cleanup_metro
    exit 1
  fi
fi

# ── Build succeeded — take launch screenshot ──────────────────────
out "BUILD_STATUS:SUCCESS"
out "Build succeeded. App should be launching on simulator..."

# Wait for the app to load the JS bundle from Metro and render.
# The app needs to: connect to Metro → download bundle → parse → render.
# This can take 10-20s on first launch (bundle compilation).
out "Waiting for app to load JS bundle and render (up to 30s)..."
APP_READY=false
for i in $(seq 1 15); do
  sleep 2
  # Check if Metro has finished processing (success or failure) by looking at its log
  if grep -qE '(Bundling complete|Bundled .* in|LOG  |200 .*\.bundle)' "$METRO_LOG" 2>/dev/null; then
    APP_READY=true
    out "Metro has served the bundle. App should be rendering."
    sleep 3  # Give the app a moment to render after bundle is loaded
    break
  fi
  if grep -qE '(Bundling failed|Unable to resolve)' "$METRO_LOG" 2>/dev/null; then
    APP_READY=true
    out "Metro bundling failed — the app will show an error screen. Taking screenshot to capture the error."
    sleep 3
    break
  fi
done

if ! $APP_READY; then
  out "Warning: Could not confirm bundle was served. Taking screenshot anyway."
  sleep 5
fi

# Take screenshot from the booted simulator
out "Taking launch screenshot..."
xcrun simctl io "$SIMULATOR_UDID" screenshot "$SCREENSHOT_PATH" 2>/dev/null || true

if [[ -f "$SCREENSHOT_PATH" ]]; then
  out "SCREENSHOT_PATH:$SCREENSHOT_PATH"
  out "Screenshot saved to $SCREENSHOT_PATH"
else
  out "SCREENSHOT_PATH:"
  out "Warning: Failed to capture screenshot (simulator may not be visible)"
fi

# ── Cleanup ──────────────────────────────────────────────────────
cleanup_metro

# Show warnings if any
WARN_LINES=$(grep -c 'warning:' "$LOG_FILE" 2>/dev/null | tr -d '[:space:]' || echo "0")
if [[ "$WARN_LINES" =~ ^[0-9]+$ ]] && [[ "$WARN_LINES" -gt 0 ]]; then
  out "($WARN_LINES warnings — see $LOG_FILE)"
fi

exit 0
